-- Writes Client/Assets/Chaos/Core/HelperRotationData.cs from the main client's rotation data
-- (client/overlay/modules/game_helperrotation/autorotation_data.lua, itself generated by server/tools/rotation_sim.py).
-- Run from the repository root: luajit unity/tools/gen_helper_rotation_data.lua [--check]
-- Needs luajit or lua5.3. --check fails when the committed file is not the one this script writes.
dofile('client/overlay/modules/game_helperrotation/autorotation_data.lua')
local D = ChaosAutoRotationData
local OUT = 'unity/Client/Assets/Chaos/Core/HelperRotationData.cs'

local function list(t)
  local out = {}
  for i, v in ipairs(t or {}) do out[i] = tostring(v) end
  return '{ ' .. table.concat(out, ', ') .. ' }'
end

local buf = {}
local function add(s) buf[#buf + 1] = s end
add('// GENERATED by unity/tools/gen_helper_rotation_data.lua from client/overlay/modules/game_helperrotation/autorotation_data.lua. Do not edit.')
add('// The Auto setup data of the helper: per class and level the best rotation of at most 5 attack spells, the class heals and the')
add('// numbers of every attack spell (cooldowns, groups, cast time) for the gap check. See HelperRotation.cs.')
add('namespace Chaos.Core')
add('{')
add('    public static partial class HelperRotationData')
add('    {')
add('        public static void Fill(System.Collections.Generic.Dictionary<int, RotClass> classes, System.Collections.Generic.Dictionary<int, RotSpell> spells)')
add('        {')
add(string.format('            Gcd = %.1f;', D.gcd or 2.0))
local ids = {}
for id in pairs(D.classes) do ids[#ids + 1] = id end
table.sort(ids)
for _, id in ipairs(ids) do
  local c = D.classes[id]
  add(string.format('            { var c = new RotClass { Id = %d, Name = %q, Ultimate = %d };', id, c.name, c.ultimate or 0))
  for _, p in ipairs(c.presets) do
    add(string.format('              c.Presets.Add(new RotPreset(%d, %.2f, new[] %s, new[] %s));', p.level, p.gap, list(p.spells), list(p.creatures)))
  end
  if c.extras and #c.extras > 0 then add(string.format('              c.Extras.AddRange(new[] %s);', list(c.extras))) end
  for _, h in ipairs(c.heals or {}) do
    add(string.format('              c.Heals.Add(new RotHeal(%d, %d));', h.id, h.level))
  end
  add(string.format('              classes[%d] = c; }', id))
end
local sids = {}
for id in pairs(D.spells) do sids[#sids + 1] = id end
table.sort(sids)
for _, id in ipairs(sids) do
  local s = D.spells[id]
  add(string.format('            spells[%d] = new RotSpell { Id = %d, Name = %q, Words = %q, Cooldown = %d, GroupCooldown = %d, SecondaryGroup = %q, SecondaryCooldown = %d, Cast = %d, Area = %s, Chi = %s };',
    id, id, s.name, s.words, s.cooldown, s.groupCooldown, s.secondaryGroup, s.secondaryCooldown, s.cast, tostring(s.area), tostring(s.chi)))
end
add('        }')
add('    }')
add('}')
local text = table.concat(buf, '\n') .. '\n'

if arg and arg[1] == '--check' then
  local f = io.open(OUT, 'rb')
  local have = f and f:read('*a') or nil
  if f then f:close() end
  if have ~= text then
    io.stderr:write('HelperRotationData.cs is out of date: run luajit unity/tools/gen_helper_rotation_data.lua\n')
    os.exit(1)
  end
  print('HelperRotationData.cs: ok')
else
  local f = assert(io.open(OUT, 'wb'))
  f:write(text)
  f:close()
  print('wrote ' .. OUT .. ' (' .. #text .. ' bytes)')
end
